import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"水天需","description":"周易折中 - 水天需","frontmatter":{"title":"水天需","description":"周易折中 - 水天需"},"headers":[],"relativePath":"classics/zhezhong/011.md","filePath":"classics/zhezhong/011.md"}'),h={name:"classics/zhezhong/011.md"};function p(n,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="水天需" tabindex="-1">水天需 <a class="header-anchor" href="#水天需" aria-label="Permalink to “水天需”">​</a></h1><h3 id="程傳" tabindex="-1">程傳 <a class="header-anchor" href="#程傳" aria-label="Permalink to “程傳”">​</a></h3><p>序卦曰：蒙者，蒙也，物之稚也。物稚不可不飬也，故受之以需。需者，飲食之道也。夫物之㓜稚，必待飬而成。飬物之所需者，飲食也，故曰需者飲食之道也。雲上於天，有蒸潤之象，飲食所以潤益於物，故需為飲食之道，所以次蒙也。卦之大意須待之義，序卦取所湏之大者耳。乾健之性必進者也，乃處坎險之下，險為之阻，故須待而後進也。</p><p>需：有孚，光亨，貞吉。利涉大川。</p><h3 id="本義" tabindex="-1">本義 <a class="header-anchor" href="#本義" aria-label="Permalink to “本義”">​</a></h3><p>需待也，以幹遇坎。乾健坎險，以剛遇險而不遽進，以䧟於險，待之義也。孚，信之在中者也。其卦九五以坎體中實，陽剛中正而居尊位，為有孚得正之象。坎水在前，乾健臨之，將涉水而不輕進之象。故佔者為有所待而能有信，則光亨矣；若又得正則吉，而利渉大川。正固無所不利，而渉川尤貴於能待，則不欲速而犯難也。</p><h3 id="程傳-1" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-1" aria-label="Permalink to “程傳”">​</a></h3><p>需者湏待也。以二體言之，幹之剛健上進而遇險，未能進也，故為需待之義。以卦才言之，五居君位，為需之主，有剛健中正之徳而誠信充實於中，中實有孚也。有孚則光明而能亨通，得貞正而吉也。以此而需，何所不濟？雖險無難矣，故利渉大川也。凡貞吉，有既正且吉者，有得正則吉者，當辨也。</p><h3 id="集說" tabindex="-1">集說 <a class="header-anchor" href="#集說" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>朱子語類雲 ：需者寧耐之意。以剛遇險，時節如此，只得寧耐以待之。且如渉川者，多以不能寧耐致覆溺之禍，故需卦首言利渉大川。</p></li><li><p>項氏安世曰 ：需非終不進也，抱實而遇險，有待而後進也。凡待者皆以其中有可待之實也。我實有之，但能少待，必有光亨之理。若其無之，何待之有？故曰需有孚光亨。光亨者不可以盈，必敬慎以終之，故曰貞吉。信能行此，則其待不虛，其進不溺，故曰利渉大川。有孚光亨貞吉者，需之道也；利渉大川者，需之效也。</p></li><li><p>胡氏炳文曰 ：需而無實無光，且亨之時，需而非正則無吉，且利之理。世有心雖誠實而處事或有未正者，故曰孚又曰貞。</p></li><li><p>林氏希元曰 ：凡人作事皆責成於目前，其間多有阻礙而目前不可成者，其勢不容於不待。然不容不待者，其心多非所樂，其待也未必出於中誠，不免於急迫覬望之意。如此則懐抱不開，胸中許多闇昧抑塞而不光明豁逹。故聖人特發有孚之義，蓋遇事勢之未可為，即安於義命從容以待機㑹而不切切焉以厚覬望，則其待也出於真實而非虛假矣。如此則心逸日休，胸襟灑落而無滯礙，不亦光明豁逹乎？然使心安於需而事或未出於正，則將來亦未必可成。必也所需之事皆出於正而無行險僥倖之為，則功深而效得，時動而事起，曏者之所需而今皆就緒矣，故吉。</p></li></ul><p>象曰：雲上於天，需；君子以飲食宴樂</p><h3 id="本義-1" tabindex="-1">本義 <a class="header-anchor" href="#本義-1" aria-label="Permalink to “本義”">​</a></h3><p>雲上於天，無所復為，待其陰陽之和而自雨。爾事之當需者，亦不容更有所為，但飲食宴樂，俟其自至而已。一有所為，則非需也。</p><h3 id="程傳-2" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-2" aria-label="Permalink to “程傳”">​</a></h3><p>雲氣蒸而上升於天，必待陰陽和洽然後成雨。雲方上於天，未成雨也，故為須待之義。陰陽之氣交感而未成雨澤，猶君子畜其才德而未施於用也。君子觀雲上於天，需而為雨之象，懐其道德，安以待時。飲食以養其氣體，宴樂以和其心志，所謂居易以俟命也。</p><h3 id="集說-1" tabindex="-1">集說 <a class="header-anchor" href="#集說-1" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>孔氏穎達曰 ：不言“天上有云”，而言“雲上於天”者，若是“天上有云”，無以見欲雨之義。故云“雲上於天”，是天之慾雨，待時而落，所以明需。</p></li><li><p>胡氏瑗曰 ：飲食者，所以養身也；宴樂者，所以寧神也。是亦樂天知命，居易俟時耳。</p></li><li><p>朱子語類 ：需待也，以飲食宴樂謂更無所為，待之而已。待之須有至時，學道者亦猶是也。</p></li><li><p>吳氏澄曰 ：宴者，身安而他無所營；作樂者，心愉而他無所謀慮也。飲食則素其位，而宴樂則不願乎外也。</p></li><li><p>谷氏家傑曰 ：雲上於天，而後可以待雨。君子有為於前，而後可以待治。不然，不幾於坐廢乎？</p></li></ul><p>彖曰：需，須也，險在前也。剛健而不陷，其義不困窮矣。</p><h3 id="本義-2" tabindex="-1">本義 <a class="header-anchor" href="#本義-2" aria-label="Permalink to “本義”">​</a></h3><p>此以卦徳釋卦名義。</p><h3 id="程傳-3" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-3" aria-label="Permalink to “程傳”">​</a></h3><p>需之義須也，以險在於前，未可遽進，故需待而行也。以幹之剛健而能需待，不輕動，故不陷於險，其義不至於困窮也。剛健之人，其動必躁，乃能需待而動，處之至善者也。故夫子贊之雲，其義不困窮矣。</p><h3 id="集說-2" tabindex="-1">集說 <a class="header-anchor" href="#集說-2" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>王氏申子曰：需者，坎險在前，須而後進也。惟剛則內有所主，故能需；惟健則動不可御，故能濟。</p></li><li><p>蔡氏清曰：以剛遇險而不遽進以陷於險者，蓋陰柔不能寧耐，乾剛則沈毅不苟而能寧耐。所謂“幹天下之至健”也，徳行恆易以知險。</p></li></ul><p>需有孚，光亨貞吉，位乎天位以正中也。利涉大川，往有功也。</p><h3 id="本義-3" tabindex="-1">本義 <a class="header-anchor" href="#本義-3" aria-label="Permalink to “本義”">​</a></h3><p>以卦體及兩象釋卦辭。</p><h3 id="程傳-4" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-4" aria-label="Permalink to “程傳”">​</a></h3><p>五以剛實居中為孚之象，而得其所需，亦有為孚之義。以乾剛而至誠，故其徳光明而能亨通，得貞正而吉也。所以能然者，以居天位而得正中也。居天位指五，以正中兼二言，故云正中。既有孚而貞正，雖涉險阻，往則有功也。需道之至善也，以乾剛而能需，何所不利？</p><h3 id="集說-3" tabindex="-1">集說 <a class="header-anchor" href="#集說-3" aria-label="Permalink to “集說”">​</a></h3><ul><li>谷氏家傑曰：此卦合坎幹成需，惟幹易而知險，故曰剛健曰正中。見有天徳者能需也。</li></ul><p>初九：需於郊，利用恆，無咎。</p><h3 id="本義-4" tabindex="-1">本義 <a class="header-anchor" href="#本義-4" aria-label="Permalink to “本義”">​</a></h3><p>郊曠逺之地，未近於險之象也。而初九陽剛，又有能常於其所之象，故戒佔者能如是則無咎也。</p><h3 id="程傳-5" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-5" aria-label="Permalink to “程傳”">​</a></h3><p>需者以遇險故需而後進，初最逺於險，故為需於郊。郊曠逺之地也，處於曠逺，利在安守其常，則無咎也。不能安常，則躁動犯難，豈能需於逺而無過也？</p><h3 id="集說-4" tabindex="-1">集說 <a class="header-anchor" href="#集說-4" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>孔氏穎逹曰 ：難在於坎，初九去難既逺，故待於郊。郊者，境上之地，去水逺也。恆，常也。逺難待時以避其害，故宜保守其常，所以無咎。</p></li><li><p>梁氏寅曰 ：需下三爻以去險逺近為吉凶。初以陽處下，最逺於險，故為需於郊之象。郊荒逺之地也，而君子安處焉，故云利用恆。</p></li></ul><p>象曰：需於郊，不犯難行也；利用恆，無咎，未失常也</p><h3 id="程傳-6" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-6" aria-label="Permalink to “程傳”">​</a></h3><p>處曠遠者不犯冒險難而行也。陽之為物，剛健上進者也。初能需待於曠遠之地，不犯險難而進，復宜安處不失其常，則可以無咎矣。雖不進而志動者，不能安其常也。君子之需時也，安靜自守，志雖有須而恬然若將終身焉，乃能用常也。</p><h3 id="集說-5" tabindex="-1">集說 <a class="header-anchor" href="#集說-5" aria-label="Permalink to “集說”">​</a></h3><ul><li>孫氏質卿曰 ：不犯難而行便是常，不失常便是恆德。人惟中無常主，或為才能所使，或為意氣所動，或為事勢所激，雖犯難而不顧耳。所以不失常最難，飲食宴樂不失常也。若能不失常，更有何事？</li></ul><p>九二：需於沙，小有言，終吉。</p><h3 id="本義-5" tabindex="-1">本義 <a class="header-anchor" href="#本義-5" aria-label="Permalink to “本義”">​</a></h3><p>沙則近於險矣，言語之傷亦災害之小者，漸進近坎，故有此象。剛中能需，故得終吉。戒佔者當如是也。</p><h3 id="程傳-7" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-7" aria-label="Permalink to “程傳”">​</a></h3><p>坎為水，水近則有沙。二去險漸近，故為需於沙。漸近於險難，雖未至於患害，已小有言矣。凡患難之辭大小有殊，小者至於有言，言語之傷至小者也。二以剛陽之才而居柔守中，寛裕自處，需之善也。雖去險漸近而未至於險，故小有言語之傷而無大害，終得其吉也。</p><h3 id="集說-6" tabindex="-1">集說 <a class="header-anchor" href="#集說-6" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>孔氏穎逹曰 ：沙是水旁之地，去水漸近，故難稍近，而小有言。但履健居中以待要㑹，終得其吉也。</p></li><li><p>胡氏炳文曰 ：初最逺坎，利用恆乃無咎；九二漸近坎，小有言矣，而曰終吉者。初九以剛居剛，恐其躁急，故雖逺險猶有戒辭；九二以剛居柔，寛而得中，故雖近險而不害其為吉。</p></li></ul><p>象曰：需於沙衍，在中也；雖小有言，以吉終也</p><h3 id="本義-6" tabindex="-1">本義 <a class="header-anchor" href="#本義-6" aria-label="Permalink to “本義”">​</a></h3><p>衍，寬意。以寬居中，不急進也。</p><h3 id="程傳-8" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-8" aria-label="Permalink to “程傳”">​</a></h3><p>衍，寬綽也。二雖近險，而以寬裕居中，故雖小有言語及之，終得其吉。善處者也。</p><h3 id="集說-7" tabindex="-1">集說 <a class="header-anchor" href="#集說-7" aria-label="Permalink to “集說”">​</a></h3><ul><li>楊氏簡曰 ：衍在中者，言胸中寬衍平夷，初不以進動其心，亦不以小言動其心。夫如是，終吉。以九二得其道故也。</li></ul><p>九三：需於泥，致寇至。</p><h3 id="本義-7" tabindex="-1">本義 <a class="header-anchor" href="#本義-7" aria-label="Permalink to “本義”">​</a></h3><p>泥將䧟於險矣，寇則害之大者。九三去䧟愈近，而過剛不中，故其象如此。</p><h3 id="程傳-9" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-9" aria-label="Permalink to “程傳”">​</a></h3><p>泥逼於水也，既進逼於險，當致寇難之至也。三剛而不中，又居健體之上，有進動之象，故致寇也。苟非敬慎，則致䘮敗矣。</p><h3 id="集說-8" tabindex="-1">集說 <a class="header-anchor" href="#集說-8" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>王氏申子曰 ：泥則切近水矣，險已近而又以剛用剛而進逼之，是招致寇難之至也。</p></li><li><p>龔氏煥曰 ：郊、沙、泥之象，視坎水逺近而為言者也。易之取象如此。</p></li></ul><p>象曰：需於泥，災在外也；自我致寇，敬慎不敗也</p><h3 id="本義-8" tabindex="-1">本義 <a class="header-anchor" href="#本義-8" aria-label="Permalink to “本義”">​</a></h3><p>外謂外卦。敬慎不敗，發明佔外之佔，聖人示人之意切矣。</p><h3 id="程傳-10" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-10" aria-label="Permalink to “程傳”">​</a></h3><p>三切逼上體之險難，故云災在外也。災，患難之通稱，對眚而言則分也。三之致寇，由己進而迫之，故云自我致寇。自己致，若能敬慎量宜而進，則無喪敗也。需之時，須而後進也，其義在相時而動，非戒其不得進也，直使敬慎毋失其宜耳。</p><h3 id="集說-9" tabindex="-1">集說 <a class="header-anchor" href="#集說-9" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>朱子語類 ：問敬慎，曰：“敬字大，慎字細。如人行路，一直恁地去便是敬；前面險處，防有吃跌便是慎。慎是惟恐有失之之意。如思慮兩字，思是恁地思去，慮是怕不恁地底意思。”</p></li><li><p>項氏安世曰 ：寇雖在外，然亦不自至，我有以致之則至。我敬慎而無失，則雖與之逼亦無敗理。</p></li><li><p>丘氏富國曰 ：坎險在外，未嘗逼人，由人急於求進，自逼於險以致禍敗。象以“自我”釋之，明致災之由不在他人也。</p></li></ul><p>六四：需於血，出自穴。</p><h3 id="本義-9" tabindex="-1">本義 <a class="header-anchor" href="#本義-9" aria-label="Permalink to “本義”">​</a></h3><p>血者殺傷之地，穴者險䧟之所。四交坎體，入乎險矣，故為需於血之象。然柔得其正，需而不進，故又為出自穴之象。佔者如是，則雖在傷地，而終得出也。</p><h3 id="程傳-11" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-11" aria-label="Permalink to “程傳”">​</a></h3><p>四以陰柔之質，處於險而下，當三陽之進，傷於險難者也，故云需於血。既傷於險難，則不能安處，必失其居，故云出自穴。穴，物之所安也。順以從時，不競於險難，所以不至於兇也。以柔居陰，非能競者也。若陽居之，則必兇矣。蓋無中正之徳，徒以剛競於險，適足以致兇耳。</p><h3 id="集說-10" tabindex="-1">集說 <a class="header-anchor" href="#集說-10" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>朱子語類問 ：程傳釋穴為“物之所安”，曰：“穴是陷處，喚作所安不得。柔得正了，需而不進，故能出於坎陷。”</p></li><li><p>楊氏啟新曰 ：剛者能需，柔亦能需，何也？剛柔皆有善惡。剛之需，猶幹之健而知險也；柔之需，猶坤之簡而知阻也。</p></li></ul><p>象曰：需於血，順以聽也</p><h3 id="程傳-12" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-12" aria-label="Permalink to “程傳”">​</a></h3><p>四以陰柔居於險難之中，不能固處，故退出自穴。蓋陰柔不能與時競，不能處則退，是順從以聽於時，所以不至於兇也。</p><h3 id="集說-11" tabindex="-1">集說 <a class="header-anchor" href="#集說-11" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>楊氏簡曰 ：六四入險而傷，然不言吉凶何也？能需而退聽故也。易之為道，無所不通。雖如四之入險而傷，其處之亦有道。六與四皆柔，故有順聽之象。</p></li><li><p>吳氏澄曰 ：謂六四柔順以聽從於九五也。</p></li><li><p>胡氏炳文曰 ：三能敬，則雖迫坎之險而不敗；四能順，則雖陷坎之險而可出。敬與順，固處險之道也。</p></li></ul><p>九五：需於酒食，貞吉。</p><h3 id="本義-10" tabindex="-1">本義 <a class="header-anchor" href="#本義-10" aria-label="Permalink to “本義”">​</a></h3><p>酒食宴樂之具，言安以待之。九五陽剛中正，需於尊位，故有此象。佔者如是而貞固，則得吉也。</p><h3 id="程傳-13" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-13" aria-label="Permalink to “程傳”">​</a></h3><p>五以陽剛居中得正，位乎天位，克盡其道矣。以此而需，何需不獲？故宴安酒食以俟之，所湏必得也。既得貞正，而所需必遂，可謂吉矣。</p><h3 id="集說-12" tabindex="-1">集說 <a class="header-anchor" href="#集說-12" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>鄭氏維嶽曰 ：《繫辭》曰：“需者，飲食之道也。”象曰：“君子以飲食宴樂。”爻曰：“需於酒食”，以治道言，使斯民樂其樂而利其利，期治於必世，百年之後而不為近功者，湏待之義也。</p></li><li><p>喬氏中和曰 ：九五之貞吉也，豈徒以酒食雲哉？險而不䧟，中自持也。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>需之為義最廣，其大者莫如王道之以乆而成，化而不急於淺近之功；聖學之以寛而居徳，而不入於正助之弊。卦惟九五，剛健中正以居尊位，是能盡需之道者，故彖傳特舉此爻以當彖辭之義；而大象傳又特取此爻爻辭以蔽需義之全。蓋繼屯䝉之後，既治且教，而所謂休飬生息，使之樂樂而利利，漸仁摩義，使之世變而風移者，其在於需乎？觀需之卦而不知此爻之義，但以諸爻處險之偏乎一義者概之，則需與蹇、困何異哉？</p><p>象曰：酒食貞吉，以中正也</p><h3 id="程傳-14" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-14" aria-label="Permalink to “程傳”">​</a></h3><p>需於酒食而貞且吉者，以五得中正而盡其道也。</p><h3 id="集說-13" tabindex="-1">集說 <a class="header-anchor" href="#集說-13" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>梁氏寅曰 ：言以中正，見其飲宴者非耽樂也。</p></li><li><p>張氏振淵曰 ：內多欲則有求治太急之患，德惟中正，所以需合於貞而得吉。中正即孚貞意，是推原所以能需處。</p></li></ul><p>上六：入於穴，有不速之客三人來，敬之終吉。</p><h3 id="本義-11" tabindex="-1">本義 <a class="header-anchor" href="#本義-11" aria-label="Permalink to “本義”">​</a></h3><p>陰居險極，無復有需，有陷而入穴之象。下應九三，九三與下二陽需極並進，為不速客三人之象。柔不能御而能順之，有敬之之象。佔者當陷險中，然於非意之來，敬以待之，則得終吉也。</p><h3 id="程傳-15" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-15" aria-label="Permalink to “程傳”">​</a></h3><p>需以險在前，需時而後進。上六居險之終，終則變矣，在需之極，乆而得矣。陰止於六，乃安其處，故為入於穴。穴所安也，安而既止，後者必至。不速之客三人，謂下之三陽。幹之三陽，非在下之物，需時而進者也。需既極矣，故皆上進，不速不促之而自來也。上六既需得其安處，群剛之來，苟不起忌疾忿競之心，至誠盡敬以待之，雖甚剛暴，豈有侵陵之理？故終吉也。或疑以陰居三陽之上，得為安乎？曰：三陽幹體，志在上進，六陰位非所止之正，故無爭奪之意，敬之則吉也。</p><h3 id="集說-14" tabindex="-1">集說 <a class="header-anchor" href="#集說-14" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>胡氏炳文曰 ：入於穴，險極而陷之象；速者，主召客之辭；三人，幹三陽之象。下三陽非皆與上應也，有不速之象。上柔順，有敬之之象。上獨不言需，險之極無復有需也。外卦險體，二陰皆有穴象。四出自穴，而上則入於穴何哉？六四柔正能需，猶可出於險，故曰出者，許其將然也；上六柔而當險之終，無復能需，惟入於險而已，故曰入者，言其已然也。然雖已入於險，非意之來，敬之終吉。君子未嘗無處險之道也。</p></li><li><p>薛氏瑄曰 ：有不速之客三人來，敬之終吉，處橫逆之道也。</p></li><li><p>谷氏家傑曰 ：三居下卦之終而示之以敬，上居上卦之終而又示之以敬，則知處需者貴敬也。</p></li></ul><p>象曰：不速之客來，敬之終吉；雖不當位，未大失也</p><h3 id="本義-12" tabindex="-1">本義 <a class="header-anchor" href="#本義-12" aria-label="Permalink to “本義”">​</a></h3><p>以陰居上，是為當位。言不當位，未詳。</p><h3 id="程傳-16" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-16" aria-label="Permalink to “程傳”">​</a></h3><p>不當位，謂以陰而在上也。爻以六居陰為所安，象復盡其義，明陰宜在下而居上為不當位也。然能敬慎以自處，則陽不能陵，終得其吉。雖不當位，而未至於大失也。</p><h3 id="集說-15" tabindex="-1">集說 <a class="header-anchor" href="#集說-15" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>呂氏祖謙曰 ：需初九、九五、二爻之吉固不待言，至於餘四爻，如二則小有言終吉，如三之象則曰敬慎不敗，四之象則曰順以聽也，上則曰有不速之客三人來，敬之終吉。大抵天下之事，若能款曲停待，終是少錯。</p></li><li><p>蔡氏清曰 ：雖不當位，謂其陰居險極，正與困上六“困於葛藟”未當也一般。</p></li></ul><p>站長備註：</p><h3 id="關於-不當位" tabindex="-1">關於“不當位” <a class="header-anchor" href="#關於-不當位" aria-label="Permalink to “關於“不當位””">​</a></h3><p>蔡氏說法站長極為認同，曾根據“當位”、“不當位”、“位當”、“位不當”等辭做統計了一個 統計列表 ，大多數都是討論“爻的陰陽”與“位”是否匹配，唯獨此爻是特例，此爻陰居陰位，按照固定的手法去討論，這裡的“不當位”是矛盾的，所以左右揣摩衡量就有了蔡氏一樣的觀點，今見之，與古人不謀而合！</p><p>爻辭和象曰，是從卦象代表的含義和爻位代表的含義而來，而孔夫子作《象》時，不拘於固定的“位”所代表的含義，而是從整體去考慮，是脫離固定研究手法，直指道理和實際。這裡的“不當位”是從坎象而來，是居坎之極，下三陽為“不速之客”，居坎險之地，又遇剛暴的三陽（乾），是危之極，是所處的位置不當，所以象曰“雖不當位”意思是“雖處不恰當的位置”，而非指“爻的陰陽”與“位”是否匹配。</p><p>每一個爻並不是獨立的，而是和其它爻有聯繫的。一個爻的吉凶不是單從自身而言，而是和周遭的爻形成的局面而言。易的道理是以形會意，用簡單的符號組合來闡述蘊含的道理，陰陽符號和六位是固定的，是具象化的形體，如果呆板的拘泥於手法，就是把《易》完全學成了“形而下”。</p><h3 id="關於敬之" tabindex="-1">關於敬之 <a class="header-anchor" href="#關於敬之" aria-label="Permalink to “關於敬之”">​</a></h3><p>《詩經·敬之》：敬之敬之，天維顯思，命不易哉。無曰高高在上，陟降厥士，日監在茲。維予小子，不聰敬止。日就月將，學有緝熙於光明。佛時仔肩，示我顯德行。</p><p>譯文：要警戒要警戒，上天監察最明顯，保持天命真困難。不要說天高高在上，每天監視著下界，人世間它看得最分明。我雖年幼初登基，聰明戒慎莫放棄。只要天天有進步，學問就會很光明。群臣輔我擔大任，示我治國好德行。</p><p>《詩經》傳為孔子編訂，所以引用更加有說服力。按《詩經》註解雲， 敬：通“儆”，警戒。之：語氣詞。 同類詞語比如“殺雞儆猴”、“以儆效尤”、“懲一儆百”、“懲一儆眾”...都體現了警戒、告誡的意味。</p><p>這些道理無非就是一個核心，上爻面對“不速之客三人來”應該戒備，警戒。與通俗理解的“敬之”為“尊敬謹慎”相比，言辭更加嚴厲和迫切，強調了警覺的緊迫性和嚴肅性。（2024年3月10日，河北邯鄲三名初中生殺害同學一案曝光，曾為受害人占卜得此爻）。</p><p>總論</p><ul><li>蔣氏悌生曰：需待也，以剛健之才遇險陷在前，當容忍待時。用柔而主靜，若不度時勢，恃剛忿躁而驟進，取敗亡必矣。初九去險尚逺，以用恆免咎；九二漸近險，亦以用柔守中而終吉；九三已迫於險，象言敬慎不敗；六四已傷於險，以柔而不競能出自穴；上六險䧟之極，亦以能敬終吉。然則需待之時，能含忍守敬，皆可以免禍。需之時義大矣。</li></ul>',123)])])}const m=e(h,[["render",p]]);export{b as __pageData,m as default};
